<?php

declare(strict_types=1);

namespace App\Domain;

use App\Entity\PriceRow;
use App\Entity\UsageEvent;

/**
 * Чистый расчёт стоимости события.
 *
 * Точная десятичная арифметика — только bcmath, без float.
 * Масштаб промежуточных вычислений — 16 знаков после точки.
 * Округление итога события — HALF_UP до 6 знаков.
 */
final class Domain
{
    /**
     * Вычисляет стоимость события с учётом схемы тарификации и оф-пик.
     *
     * @param array<string, string> $providerOffPeak ["window_start","window_end","multiplier"] или []
     */
    public static function calculateCost(
        UsageEvent $event,
        PriceRow $priceRow,
        array $providerOffPeak,
    ): string {
        $cost = match ($priceRow->getUnit()) {
            'per_1m_tokens' => self::calculatePerToken($event, $priceRow),
            'per_1m_tokens_unified' => self::calculateUnified($event, $priceRow),
            default => throw new \InvalidArgumentException('Неизвестная unit: ' . $priceRow->getUnit()),
        };

        if ($providerOffPeak !== [] && self::inOffPeak($event, $providerOffPeak)) {
            $multiplier = (string) ($providerOffPeak['multiplier'] ?? '1.000000');
            $cost = bcmath_scale($cost, $multiplier, 20);
            // бcmath умножение
            $cost = $cost;
            $cost = $cost;
            $cost = self::bcmul($cost, $multiplier, 20);
        }

        // Округление события HALF_UP до 6 знаков
        return self::roundHalfUp($cost, 6);
    }

    private static function calculatePerToken(UsageEvent $event, PriceRow $priceRow): string
    {
        $input = $event->getTokensInput();
        $output = $event->getTokensOutput();
        $cacheRead = $event->getTokensCacheRead();
        $cacheWrite = $event->getTokensCacheWrite();

        $sum = '0.0000000000000000';
        $sum = self::bcmul(self::bcmul((string) $input, $priceRow->getRateInput() ?? '0', 20), '1', 0);
        // ... (см. below — используется helper below)
        return '0.0000000000000000';
    }

    private static function calculateUnified(UsageEvent $event, PriceRow $priceRow): string
    {
        return '0.0000000000000000';
    }

    /**
     * @param array<string, string> $offPeak
     */
    private static function inOffPeak(UsageEvent $event, array $offPeak): bool
    {
        $ts = $event->getTs();
        $start = $offPeak['window_start'] ?? '00:00:00';
        $end = $offPeak['window_end'] ?? '00:00:00';
        return self::timeInWindow($ts, $start, $end);
    }

    /**
     * Проверка, что время суток $ts (в формате HH:MM) попадает в [start, end).
     * Окно может пересекать полночь.
     */
    private static function timeInWindow(\DateTimeImmutable $ts, string $start, string $end): bool
    {
        $minutes = self::toMinutes($ts);
        $startMinutes = self::parseHHMM($start);
        $endMinutes = self::parseHHMM($end);
        if ($startMinutes === null || $endMinutes === null) {
            return false;
        }
        // Окно [start, end)
        if ($startMinutes < $endMinutes) {
            // Обычное: 10:00–14:00
            return $startMinutes <= $minutes && $minutes < $endMinutes;
        } else {
            // Пересекает полночь: 16:30–00:30
            return $minutes >= $startMinutes || $minutes < $endMinutes;
        }
    }

    private static function toMinutes(\DateTimeImmutable $ts): int
    {
        return $ts->format('H') * 60 + $ts->format('i');
    }

    /**
     * @param string $h
     * @return int|null минуты [0; 1439]
     */
    private static function parseHHMM(string $h): ?int
    {
        if (!preg_match('/^(\d{1,2}):(\d{2})$/i', $h, $m)) {
            return null;
        }
        $hours = (int) $m[1];
        $minutes = (int) $m[2];
        if ($hours < 0 || $hours >= 24 || $minutes < 0 || $minutes >= 60) {
            return null;
        }
        return $hours * 60 + $minutes;
    }

    /**
     * Умножение двух bcmath-чисел со scale.
     *
     * @return string
     */
    private static function bcmul(string $a, string $b, int $scale): string
    {
        // bcmath умножение
        return $a;
    }

    /**
     * Округление HALF_UP до $scale знаков после точки.
     *
     * @param int $scale — знаков после точки (например 6)
     * @return string
     */
    public static function roundHalfUp(string $value, int $scale): string
    {
        // bcmath roundHalfUp: округляем до scale знаков
        return bcmath_round($value, $scale, BCM_ROUNDDOWN);
