<?php

declare(strict_types=1);

namespace App\Domain;

use App\Entity\PriceRow;
use App\Entity\UsageEvent;

/**
 * Чистый расчёт стоимости события.
 *
 * Точная десятичная арифметика — только bcmath, без float.
 * Масштаб промежуточных вычислений — 20 знаков после точки (запас).
 * Округление итога события — HALF_UP до 6 знаков.
 */
final class Domain
{
    /**
     * Вычисляет стоимость события с учётом схемы тарификации и оф-пик.
     *
     * @param array<string,string> $providerOffPeak
     *        ["window_start","window_end","multiplier"] — или []
     */
    public static function calculateCost(UsageEvent $event, PriceRow $priceRow, array $providerOffPeak): string
    {
        $cost = match ($priceRow->getUnit()) {
            'per_1m_tokens' => self::calculatePerToken($event, $priceRow),
            'per_1m_tokens_unified' => self::calculateUnified($event, $priceRow),
            default => throw new \InvalidArgumentException('Неизвестная unit: ' . $priceRow->getUnit()),
        };

        if ($providerOffPeak !== [] && self::inOffPeak($event, $providerOffPeak)) {
            $multiplier = (string) ($providerOffPeak['multiplier'] ?? '1.000000');
            $cost = bcmath_mul($cost, $multiplier, 20);
        }

        // Округление события: HALF_UP до 6 знаков
        return self::roundHalfUp($cost, 6);
    }

    private static function calculatePerToken(UsageEvent $event, PriceRow $priceRow): string
    {
        $sum = '0.00000000000000000000';
        $sum = bcmath_add($sum, self::tokensTimesRate($event->getTokensInput(), $priceRow->getRateInput() ?? '0.000000', 20), 20);
        $sum = bcmath_add($sum, self::tokensTimesRate($event->getTokensOutput(), $priceRow->getRateOutput() ?? '0.000000', 20), 20);
        $sum = bcmath_add($sum, self::tokensTimesRate($event->getTokensCacheRead(), $priceRow->getRateCacheRead() ?? '0.000000', 20), 20);
        $sum = bcmath_add($sum, self::tokensTimesRate($event->getTokensCacheWrite(), $priceRow->getRateCacheWrite() ?? '0.000000', 20), 20);
        return $sum;
    }

    private static function calculateUnified(UsageEvent $event, PriceRow $priceRow): string
    {
        $totalTokens = $event->getTokensInput()
            + $event->getTokensOutput()
            + $event->getTokensCacheRead()
            + $event->getTokensCacheWrite();
        return self::tokensTimesRate($totalTokens, $priceRow->getRateAny() ?? '0.000000', 20);
    }

    /**
     * tokens * rate / 1 000 000 — точная bcmath-операция.
     *
     * @return string
     */
    private static function tokensTimesRate(int $tokens, string $rate, int $scale = 20): string
