    {
        return $this->getDoctrine()->createQueryBuilder()
            ->from(UsageEvent::class)
            ->where('u.status', '=', UsageEvent::STATUS_NEW)
            ->orderBy('u.ts')
            ->orderBy('u.provider')
            ->orderBy('u.providerRequestId')
            ->setMaxResults($limit)
            ->getQuery()
            ->getResult();
    }

